n0:createOracleFunction.n0:source:
CREATE OR REPLACE EDITIONABLE FUNCTION "%USER_NAME%"."LATEST_SESSION_DATE" (CASE_NUM NUMBER) RETURN DATE
AS
    vDate DATE;
BEGIN
    SELECT MAX(date_session)
    INTO vDate
    FROM sessions
    WHERE case_number = case_num;

    RETURN vDate;
EXCEPTION
    WHEN OTHERS THEN
        RETURN NULL;
END LATEST_SESSION_DATE;
/
